using System.Diagnostics;using System.IO;using System.Windows;using CommunityToolkit.Mvvm.ComponentModel;using CommunityToolkit.Mvvm.Input;using Microsoft.Win32;using Produktionsplanung.App.Services;namespace Produktionsplanung.App.ViewModels;
public partial class SettingsViewModel:ObservableObject{[ObservableProperty]private string companyName="OpsCompact";[ObservableProperty]private string siteName="";[ObservableProperty]private string defaultBackupDirectory=AppPaths.BackupsDirectory;[ObservableProperty]private string defaultExportDirectory=AppPaths.ExportsDirectory;[ObservableProperty]private bool autoBackupOnExit=true;[ObservableProperty]private int backupRetentionCount=10;[ObservableProperty]private string csvDelimiter=";";[ObservableProperty]private bool includeUtf8Bom=true;[ObservableProperty]private string statusMessage="";public string DatabasePath=>AppPaths.DatabasePath;public string SettingsPath=>AppPaths.SettingsPath;public SettingsViewModel()=>LoadSettings();[RelayCommand]private void SaveSettings(){try{var s=BuildSettings();AppSettingsService.Save(s);ApplySettings(s);StatusMessage="Einstellungen gespeichert.";}catch(Exception ex){StatusMessage=$"Einstellungen konnten nicht gespeichert werden: {ex.Message}";}}[RelayCommand]private void BrowseBackupDirectory(){var current=AppSettingsService.ResolveStoragePath(DefaultBackupDirectory,"Backups");var dialog=new OpenFolderDialog{Title="Standardordner für OpsCompact-Backups auswählen",InitialDirectory=Directory.Exists(current)?current:AppPaths.BackupsDirectory};if(dialog.ShowDialog()==true)DefaultBackupDirectory=AppSettingsService.ToStoredStoragePath(dialog.FolderName,"Backups");}[RelayCommand]private void BrowseExportDirectory(){var current=AppSettingsService.ResolveStoragePath(DefaultExportDirectory,"Exports");var dialog=new OpenFolderDialog{Title="Standardordner für OpsCompact-Exporte auswählen",InitialDirectory=Directory.Exists(current)?current:AppPaths.ExportsDirectory};if(dialog.ShowDialog()==true)DefaultExportDirectory=AppSettingsService.ToStoredStoragePath(dialog.FolderName,"Exports");}
 [RelayCommand]private void CreateBackup(){try{var s=BuildSettings();AppSettingsService.Save(s);var dir=AppSettingsService.ResolveStoragePath(s.DefaultBackupDirectory,"Backups");Directory.CreateDirectory(dir);var dialog=new SaveFileDialog{Title="OpsCompact-Backup speichern",Filter="OpsCompact Backup (*.kpibackup)|*.kpibackup",DefaultExt=".kpibackup",AddExtension=true,InitialDirectory=dir,FileName=$"OpsCompact-{DateTime.Now:yyyyMMdd-HHmmss}.kpibackup"};if(dialog.ShowDialog()!=true)return;var path=BackupService.CreateBackup(dialog.FileName,s);ApplySettings(s);StatusMessage=$"Backup erfolgreich erstellt: {path} · zuletzt erfolgreich {s.LastSuccessfulBackupAtLocal:g}.";}catch(Exception ex){StatusMessage=$"Backup fehlgeschlagen: {ex.Message}";}}[RelayCommand]private void RestoreBackup(){var dir=AppSettingsService.ResolveStoragePath(DefaultBackupDirectory,"Backups");var dialog=new OpenFileDialog{Title="OpsCompact-Backup wiederherstellen",Filter="OpsCompact Backup (*.kpibackup)|*.kpibackup|Alle Dateien (*.*)|*.*",InitialDirectory=Directory.Exists(dir)?dir:AppPaths.BackupsDirectory};if(dialog.ShowDialog()!=true)return;if(MessageBox.Show("Beim Wiederherstellen wird die aktuelle lokale Datenbank ersetzt. OpsCompact erstellt davor automatisch ein Sicherheitsbackup. Fortfahren?","Backup wiederherstellen",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;try{var s=BuildSettings();AppSettingsService.Save(s);dir=AppSettingsService.ResolveStoragePath(s.DefaultBackupDirectory,"Backups");Directory.CreateDirectory(dir);var safety=Path.Combine(dir,$"OpsCompact-vor-Restore-{DateTime.Now:yyyyMMdd-HHmmss}.kpibackup");BackupService.CreateBackup(safety,s);BackupService.RestoreBackup(dialog.FileName);StatusMessage=$"Backup wiederhergestellt. Sicherheitsbackup: {safety}. Bitte OpsCompact jetzt neu starten.";}catch(Exception ex){StatusMessage=$"Wiederherstellung fehlgeschlagen: {ex.Message}";}finally{if(SessionService.RequiresRestart){Application.Current.MainWindow.IsEnabled=false;MessageBox.Show(StatusMessage+"\nDie Anwendung wird jetzt geschlossen. Bitte erneut starten und anmelden.","OpsCompact wiederherstellen",MessageBoxButton.OK,MessageBoxImage.Information);Application.Current.Shutdown();}}}
 [RelayCommand]private void RestartApplication(){try{var exe=Environment.ProcessPath;if(string.IsNullOrWhiteSpace(exe)){StatusMessage="Der Anwendungspfad konnte nicht ermittelt werden.";return;}Process.Start(new ProcessStartInfo(exe){UseShellExecute=true});Application.Current.Shutdown();}catch(Exception ex){StatusMessage=$"Neustart nicht möglich: {ex.Message}";}}[RelayCommand]private void ExportAll(){try{var s=BuildSettings();AppSettingsService.Save(s);var dir=AppSettingsService.ResolveStoragePath(s.DefaultExportDirectory,"Exports");Directory.CreateDirectory(dir);var dialog=new OpenFolderDialog{Title="Zielordner für OpsCompact-CSV-Export auswählen",InitialDirectory=dir};if(dialog.ShowDialog()!=true)return;DefaultExportDirectory=AppSettingsService.ToStoredStoragePath(dialog.FolderName,"Exports");s.DefaultExportDirectory=DefaultExportDirectory;AppSettingsService.Save(s);var export=CsvExportService.ExportAll(dialog.FolderName,s);StatusMessage=$"CSV-Export erfolgreich erstellt: {export}";}catch(Exception ex){StatusMessage=$"Export fehlgeschlagen: {ex.Message}";}}[RelayCommand]private void OpenDataDirectory()=>OpenDirectory(AppPaths.RootDirectory);[RelayCommand]private void OpenBackupDirectory()=>OpenDirectory(AppSettingsService.ResolveStoragePath(DefaultBackupDirectory,"Backups"));[RelayCommand]private void OpenExportDirectory()=>OpenDirectory(AppSettingsService.ResolveStoragePath(DefaultExportDirectory,"Exports"));private void LoadSettings(){var s=AppSettingsService.Load();ApplySettings(s);StatusMessage=s.LastSuccessfulBackupAtLocal.HasValue?$"Letztes erfolgreiches Backup: {s.LastSuccessfulBackupAtLocal:g} · {s.LastSuccessfulBackupPath}":"Noch kein erfolgreiches Backup protokolliert.";}private AppSettings BuildSettings()=>new(){CompanyName=CompanyName,SiteName=SiteName,DefaultBackupDirectory=DefaultBackupDirectory,DefaultExportDirectory=DefaultExportDirectory,AutoBackupOnExit=AutoBackupOnExit,BackupRetentionCount=BackupRetentionCount,CsvDelimiter=CsvDelimiter,IncludeUtf8Bom=IncludeUtf8Bom,LastSuccessfulBackupAtLocal=AppSettingsService.Load().LastSuccessfulBackupAtLocal,LastSuccessfulBackupPath=AppSettingsService.Load().LastSuccessfulBackupPath};private void ApplySettings(AppSettings s){CompanyName=s.CompanyName;SiteName=s.SiteName;DefaultBackupDirectory=s.DefaultBackupDirectory;DefaultExportDirectory=s.DefaultExportDirectory;AutoBackupOnExit=s.AutoBackupOnExit;BackupRetentionCount=s.BackupRetentionCount;CsvDelimiter=s.CsvDelimiter;IncludeUtf8Bom=s.IncludeUtf8Bom;}private void OpenDirectory(string dir){try{if(string.IsNullOrWhiteSpace(dir))return;Directory.CreateDirectory(dir);Process.Start(new ProcessStartInfo(dir){UseShellExecute=true});}catch(Exception ex){StatusMessage=$"Ordner konnte nicht geöffnet werden: {ex.Message}";}}}
